import{_ as a,o as s,c as t,a as r,e as o}from"./chunks/framework.Cq4gzU1W.js";const g=JSON.parse('{"title":"Scratch","description":"Scratch un lenguaje de programación divertido","frontmatter":{"title":"Scratch ","description":"Scratch un lenguaje de programación divertido","weight":10,"draft":false,"icon":"fas fa-bug"},"headers":[],"relativePath":"scratch/estructuras-selectivas/index.md","filePath":"04_Scratch/04_Selectivas/index.md"}'),c={name:"scratch/estructuras-selectivas/index.md"};function i(n,e,d,u,l,p){return s(),t("div",null,[...e[0]||(e[0]=[r("p",{"{:::":""},"{{::: objetivos}} Acceder a scratch para programar Ver el entorno de ejecución",-1),o('<h1 id="estructuras-selectivas" tabindex="-1">Estructuras selectivas <a class="header-anchor" href="#estructuras-selectivas" aria-label="Permalink to &quot;Estructuras selectivas&quot;">​</a></h1><p>Hasta ahora hemos aprendido a ejecutar instrucciones de forma secuencial, es decir, una detrás de otra.</p><p>Sin embargo, <strong>no siempre queremos ejecutar todas las instrucciones</strong>. En muchas ocasiones necesitamos tomar decisiones dependiendo de determinadas condiciones.</p><p>Las <strong>estructuras selectivas</strong> permiten que un programa decida qué acciones ejecutar según se cumpla o no una condición.</p><p>Por ejemplo:</p><ul><li>🧥 <strong>Si</strong> hace frío, me pongo el abrigo.</li><li>🌧️ <strong>Si</strong> llueve, cojo el paraguas.</li><li>🎂 <strong>Si</strong> tengo 18 años o más, soy mayor de edad.</li><li>🐱 <strong>Si</strong> el personaje de Scratch toca el borde, vuelve al inicio.</li></ul><p>En programación, estas decisiones se expresan mediante <strong>condiciones</strong>, cuyo resultado siempre es verdadero o falso.</p><div class="tip custom-block"><p class="custom-block-title">💡 Idea fundamental</p><p>Las estructuras selectivas permiten que nuestros programas <strong>tomen decisiones y se comporten de manera diferente según las circunstancias</strong>.</p><p>En Scratch utilizaremos los bloques <code>si... entonces</code> y <code>si... entonces... si no</code>.</p></div><h2 id="estudio-en-scratch" tabindex="-1">Estudio en scratch <a class="header-anchor" href="#estudio-en-scratch" aria-label="Permalink to &quot;Estudio en scratch&quot;">​</a></h2><div class="iframe-container"><iframe src="https://es.wikieducator.org/index.php?curid=6651" width="100%" height="1724">WikiEducator </iframe></div>',10)])])}const h=a(c,[["render",i]]);export{g as __pageData,h as default};
